/* Global reset and base rules */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

[hidden] {
  display: none !important;
}

:root {
  --color-bg: #1c202a;
  --color-card: #272d3b;
  --color-card-border: #444f67;
  --color-accent: #f7b731;
  --color-accent-hover: #fed330;
  --color-text: #f0f3f8;
  --color-text-dim: #9aa5b9;
  --color-shadow: #0f1218;
  --color-danger: #fc5c65;
  --font-family: 'Courier New', Courier, monospace, system-ui, sans-serif;
}

body {
  min-height: 100vh;
  background-color: var(--color-bg);
  color: var(--color-text);
  font-family: var(--font-family);
  font-size: 16px;
  line-height: 1.5;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px 12px;
}

.counter-app {
  width: 100%;
  max-width: 680px;
  background: var(--color-card);
  border: 4px solid var(--color-card-border);
  box-shadow: 6px 6px 0px var(--color-shadow);
  padding: 24px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  text-align: center;
}

.app-title {
  font-size: 1.6rem;
  letter-spacing: 2px;
  color: var(--color-accent);
  text-shadow: 2px 2px 0px var(--color-shadow);
}

.app-subtitle {
  font-size: 1rem;
  color: var(--color-text-dim);
  margin-top: 4px;
}

/* Total summary banner */
.total-display-card {
  background: #191e29;
  border: 3px solid var(--color-card-border);
  box-shadow: 3px 3px 0px var(--color-shadow);
  padding: 16px;
  text-align: center;
}

.total-label {
  font-size: 1rem;
  color: var(--color-text-dim);
  letter-spacing: 1.5px;
  font-weight: bold;
}

.total-value {
  font-size: 2.4rem;
  font-weight: bold;
  color: var(--color-accent);
  margin-top: 4px;
}

/* Grid for vehicle cards */
.controls-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}

.counter-card {
  background: #1f2533;
  border: 3px solid var(--color-card-border);
  box-shadow: 3px 3px 0px var(--color-shadow);
  padding: 16px 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.pixel-icon {
  image-rendering: pixelated;
  background: #151922;
  border: 2px solid var(--color-card-border);
  padding: 4px;
  display: block;
}

/* Buttons */
.pixel-btn {
  width: 100%;
  font-family: inherit;
  font-size: 1rem;
  font-weight: bold;
  padding: 10px 8px;
  background-color: var(--color-accent);
  color: #12151c;
  border: 3px solid #12151c;
  box-shadow: 3px 3px 0px var(--color-shadow);
  cursor: pointer;
  transition: transform 0.05s ease, box-shadow 0.05s ease, background-color 0.1s ease;
}

.pixel-btn:hover:not(:disabled) {
  background-color: var(--color-accent-hover);
}

.pixel-btn:active:not(:disabled) {
  transform: translate(2px, 2px);
  box-shadow: 1px 1px 0px var(--color-shadow);
}

.pixel-btn:focus-visible {
  outline: 3px solid #ffffff;
  outline-offset: 2px;
}

.pixel-btn:disabled {
  background-color: #3b4458;
  color: #727e96;
  border-color: #272d3b;
  cursor: not-allowed;
  box-shadow: none;
  transform: none;
}

/* Stats readout */
.stat-box {
  width: 100%;
  display: flex;
  justify-content: space-between;
  font-size: 0.95rem;
  padding: 2px 4px;
  border-bottom: 1px dashed var(--color-card-border);
}

.stat-label {
  color: var(--color-text-dim);
}

.stat-count,
.stat-pct {
  font-weight: bold;
  color: var(--color-text);
}

/* Actions / Undo */
.actions-section {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  margin-top: 8px;
}

.undo-btn {
  max-width: 240px;
  background-color: #384257;
  color: var(--color-text);
}

.undo-btn:hover:not(:disabled) {
  background-color: #48546f;
}

.status-msg {
  font-size: 0.9rem;
  color: var(--color-text-dim);
  min-height: 1.4em;
}

/* Responsive styling */
@media (max-width: 580px) {
  .controls-grid {
    grid-template-columns: 1fr;
  }

  .counter-card {
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
  }

  .pixel-icon {
    flex-shrink: 0;
  }

  .pixel-btn {
    flex: 1 1 140px;
  }

  .stat-box {
    width: 48%;
  }
}

(function () {
  'use strict';

  // Application State
  var counts = {
    car: 0,
    bus: 0,
    bike: 0
  };
  var history = [];

  // DOM Element References
  var totalDisplay = document.getElementById('total-count');
  var undoButton = document.getElementById('btn-undo');
  var statusMessage = document.getElementById('status-msg');

  var vehicleElements = {
    car: {
      button: document.getElementById('btn-car'),
      count: document.getElementById('count-car'),
      pct: document.getElementById('pct-car'),
      canvas: document.getElementById('icon-car')
    },
    bus: {
      button: document.getElementById('btn-bus'),
      count: document.getElementById('count-bus'),
      pct: document.getElementById('pct-bus'),
      canvas: document.getElementById('icon-bus')
    },
    bike: {
      button: document.getElementById('btn-bike'),
      count: document.getElementById('count-bike'),
      pct: document.getElementById('pct-bike'),
      canvas: document.getElementById('icon-bike')
    }
  };

  // Pure Canvas Pixel Drawing Helper
  function drawPixelArt(canvas, matrix, colorMap, scale) {
    var ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (var r = 0; r < matrix.length; r++) {
      for (var c = 0; c < matrix[r].length; c++) {
        var key = matrix[r][c];
        if (key && colorMap[key]) {
          ctx.fillStyle = colorMap[key];
          ctx.fillRect(c * scale, r * scale, scale, scale);
        }
      }
    }
  }

  // Draw Vehicle Pixel Icons
  function renderIcons() {
    var colors = {
      A: '#f7b731',
      B: '#20bf6b',
      C: '#0fb9b1',
      W: '#ffffff',
      D: '#0f1218'
    };

    // Car (16x10 pixels)
    var carMatrix = [
      '................',
      '.....AAAA.......',
      '...AAWWWWAA.....',
      '..AAWWWWWWAA....',
      '.AAAAAAAAAAAAA..',
      'AAAAAAAAAAAAAAA.',
      '.AADDAAAAAADDA..',
      '..DD........DD..',
      '................',
      '................'
    ];

    // Bus (16x10 pixels)
    var busMatrix = [
      '................',
      '.BBBBBBBBBBBBB..',
      '.BWWWBWWWBWWWB..',
      '.BWWWBWWWBWWWB..',
      '.BBBBBBBBBBBBB..',
      '.BBBBBBBBBBBBB..',
      '.BBDDBBBBBDDBB..',
      '..DD........DD..',
      '................',
      '................'
    ];

    // Bike (16x10 pixels)
    var bikeMatrix = [
      '................',
      '.......CCC......',
      '......C...C.....',
      '....CC.C........',
      '...CDD.CDD......',
      '..D..D.D..D.....',
      '..D..D.D..D.....',
      '...DD...DD......',
      '................',
      '................'
    ];

    drawPixelArt(vehicleElements.car.canvas, carMatrix, colors, 4);
    drawPixelArt(vehicleElements.bus.canvas, busMatrix, colors, 4);
    drawPixelArt(vehicleElements.bike.canvas, bikeMatrix, colors, 4);
  }

  // Update UI and Percentages
  function updateUI(status) {
    var total = counts.car + counts.bus + counts.bike;
    totalDisplay.textContent = total;

    var types = ['car', 'bus', 'bike'];
    for (var i = 0; i < types.length; i++) {
      var type = types[i];
      var count = counts[type];
      vehicleElements[type].count.textContent = count;
      var percentage = total > 0 ? ((count / total) * 100).toFixed(1) + '%' : '0%';
      vehicleElements[type].pct.textContent = percentage;
    }

    undoButton.disabled = history.length === 0;
    if (status) {
      statusMessage.textContent = status;
    }
  }

  // Action Handler: Increment
  function addVehicle(type) {
    counts[type] += 1;
    history.push(type);
    var displayName = type.toUpperCase();
    updateUI('Added 1 ' + displayName);
  }

  // Action Handler: Undo
  function undoLast() {
    if (history.length === 0) return;
    var lastType = history.pop();
    if (counts[lastType] > 0) {
      counts[lastType] -= 1;
    }
    var displayName = lastType.toUpperCase();
    updateUI('Undid last ' + displayName);
  }

  // Event Listeners Initialization
  function init() {
    renderIcons();

    vehicleElements.car.button.addEventListener('click', function () {
      addVehicle('car');
    });

    vehicleElements.bus.button.addEventListener('click', function () {
      addVehicle('bus');
    });

    vehicleElements.bike.button.addEventListener('click', function () {
      addVehicle('bike');
    });

    undoButton.addEventListener('click', undoLast);

    updateUI('Ready to count');
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
